import{c as e,Q as a,j as o,m as i}from"./chunks/framework.DoOjWOm2.js";const u=JSON.parse('{"title":"Photos Library Documentation","description":"","frontmatter":{},"headers":[],"relativePath":"libraries/photos.md","filePath":"libraries/photos.md"}'),d={name:"libraries/photos.md"};function s(r,t,n,l,h,p){return a(),o("div",null,[...t[0]||(t[0]=[i(`<h1 id="photos-library-documentation" tabindex="-1">Photos Library Documentation <a class="header-anchor" href="#photos-library-documentation" aria-label="Permalink to &quot;Photos Library Documentation&quot;">​</a></h1><p><strong>Since:</strong> 0.16.0</p><p>The photos library provides photo browsing with EXIF metadata extraction, album organization, and slideshow functionality.</p><h2 id="supported-formats" tabindex="-1">Supported Formats <a class="header-anchor" href="#supported-formats" aria-label="Permalink to &quot;Supported Formats&quot;">​</a></h2><p>The photo library supports the following image formats:</p><table tabindex="0"><thead><tr><th>Format</th><th>Extension</th><th>EXIF Support</th><th>Notes</th></tr></thead><tbody><tr><td>JPEG</td><td>jpg, jpeg</td><td>✅ Full</td><td>Best for photos; EXIF extraction via <code>exif_read_data()</code></td></tr><tr><td>PNG</td><td>png</td><td>❌ Basic</td><td>Dimensions only; no camera metadata</td></tr><tr><td>TIFF</td><td>tiff, tif</td><td>❌ Basic</td><td>Dimensions only</td></tr><tr><td>WebP</td><td>webp</td><td>❌ Basic</td><td>Dimensions only</td></tr><tr><td>HEIC</td><td>heic, heif</td><td>⚠️ Limited</td><td>Requires ImageMagick extension; graceful fallback if unavailable</td></tr></tbody></table><h2 id="exif-fields-extracted" tabindex="-1">EXIF Fields Extracted <a class="header-anchor" href="#exif-fields-extracted" aria-label="Permalink to &quot;EXIF Fields Extracted&quot;">​</a></h2><p>When scanning photos, the following EXIF metadata is extracted and stored in each media item&#39;s <code>metadata_json</code>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>camera_make</code></td><td>string</td><td>Camera manufacturer (e.g., &quot;Canon&quot;, &quot;Nikon&quot;)</td></tr><tr><td><code>camera_model</code></td><td>string</td><td>Camera model (e.g., &quot;EOS 5D Mark IV&quot;)</td></tr><tr><td><code>lens</code></td><td>string</td><td>Lens model (if available in EXIF)</td></tr><tr><td><code>aperture</code></td><td>string</td><td>Aperture value (e.g., &quot;f/2.8&quot;)</td></tr><tr><td><code>iso</code></td><td>int</td><td>ISO sensitivity</td></tr><tr><td><code>shutter_speed</code></td><td>string</td><td>Exposure time (e.g., &quot;1/250&quot;)</td></tr><tr><td><code>focal_length</code></td><td>string</td><td>Focal length (e.g., &quot;50mm&quot;)</td></tr><tr><td><code>width</code></td><td>int</td><td>Image width in pixels</td></tr><tr><td><code>height</code></td><td>int</td><td>Image height in pixels</td></tr><tr><td><code>orientation</code></td><td>int</td><td>EXIF orientation code (1-8)</td></tr><tr><td><code>orientation_name</code></td><td>string</td><td>Human-readable orientation</td></tr><tr><td><code>date_taken_unix</code></td><td>int</td><td>Unix timestamp when photo was taken</td></tr><tr><td><code>gps_lat</code></td><td>float</td><td>GPS latitude coordinate</td></tr><tr><td><code>gps_lng</code></td><td>float</td><td>GPS longitude coordinate</td></tr><tr><td><code>gps_alt</code></td><td>float</td><td>GPS altitude in meters</td></tr></tbody></table><h2 id="album-organization" tabindex="-1">Album Organization <a class="header-anchor" href="#album-organization" aria-label="Permalink to &quot;Album Organization&quot;">​</a></h2><p>Photos are automatically grouped into albums based on the date they were taken:</p><ul><li><strong>Date-based albums</strong>: Photos are grouped by <code>YYYY-MM-DD</code> of <code>date_taken_unix</code></li><li>Albums are sorted with most recent first</li><li>Each album shows a cover photo and photo count</li></ul><h2 id="api-endpoints" tabindex="-1">API Endpoints <a class="header-anchor" href="#api-endpoints" aria-label="Permalink to &quot;API Endpoints&quot;">​</a></h2><h3 id="albums" tabindex="-1">Albums <a class="header-anchor" href="#albums" aria-label="Permalink to &quot;Albums&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Endpoint</th><th>Description</th></tr></thead><tbody><tr><td>GET</td><td><code>/photo/albums</code></td><td>List all albums (grouped by date)</td></tr><tr><td>GET</td><td><code>/photo/albums/{id}</code></td><td>Get specific album with photos</td></tr></tbody></table><h3 id="photos" tabindex="-1">Photos <a class="header-anchor" href="#photos" aria-label="Permalink to &quot;Photos&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Endpoint</th><th>Description</th></tr></thead><tbody><tr><td>GET</td><td><code>/photo/photos</code></td><td>List all photos</td></tr><tr><td>GET</td><td><code>/photo/photos/{id}</code></td><td>Get photo with full EXIF data</td></tr><tr><td>GET</td><td><code>/photo/photos/{id}/thumbnail?w=300&amp;h=300&amp;fit=cover</code></td><td>Get resized thumbnail</td></tr><tr><td>GET</td><td><code>/photo/photos/{id}/full</code></td><td>Get full-resolution photo</td></tr></tbody></table><h3 id="slideshow" tabindex="-1">Slideshow <a class="header-anchor" href="#slideshow" aria-label="Permalink to &quot;Slideshow&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Endpoint</th><th>Description</th></tr></thead><tbody><tr><td>GET</td><td><code>/photo/slideshow?album_id=xxx&amp;interval=5</code></td><td>Get slideshow data</td></tr></tbody></table><h2 id="thumbnail-generation" tabindex="-1">Thumbnail Generation <a class="header-anchor" href="#thumbnail-generation" aria-label="Permalink to &quot;Thumbnail Generation&quot;">​</a></h2><p>Thumbnails are generated on-demand using PHP&#39;s GD library:</p><ul><li>Default size: 300×300 pixels</li><li>Fit modes: <code>cover</code> (crop to fill) or <code>contain</code> (letterbox)</li><li>Thumbnails are served with <code>Cache-Control: public, max-age=86400</code></li><li>Full photos use <code>Cache-Control: public, max-age=31536000</code> (1 year)</li></ul><h2 id="slideshow-player" tabindex="-1">Slideshow Player <a class="header-anchor" href="#slideshow-player" aria-label="Permalink to &quot;Slideshow Player&quot;">​</a></h2><p>The slideshow player features:</p><ul><li><strong>Auto-advance</strong>: Configurable interval (default 5 seconds)</li><li><strong>Keyboard controls</strong>: Arrow keys (←/→), Space (play/pause), Escape (exit)</li><li><strong>Touch/swipe</strong>: Swipe left/right on mobile devices</li><li><strong>Thumbnail strip</strong>: Quick navigation at bottom</li><li><strong>Caption display</strong>: Shows camera info and date</li></ul><h2 id="deferred-features" tabindex="-1">Deferred Features <a class="header-anchor" href="#deferred-features" aria-label="Permalink to &quot;Deferred Features&quot;">​</a></h2><p>The following features are planned for future releases:</p><ul><li><strong>Geotag clustering / map view</strong>: Photos with GPS coordinates will be plottable on a map</li><li><strong>Thumbnail caching</strong>: Disk-based cache for generated thumbnails</li><li><strong>Photo editing</strong>: Basic editing (rotate, crop)</li><li><strong>Sharing</strong>: Generate shareable links for photos/albums</li><li><strong>Backup integration</strong>: Export photos to cloud storage</li></ul><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>No special configuration is required for the photos library. The following optional settings may be added in <code>config/server.php</code>:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Future photo library settings (not yet implemented)</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;photo&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;thumbnail_size&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 300</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;slideshow_interval&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;enable_map_view&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Future: Enable geotag clustering</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span></code></pre></div><h2 id="known-limitations" tabindex="-1">Known Limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known Limitations&quot;">​</a></h2><ol><li><strong>HEIC/HEIF support</strong>: Requires ImageMagick extension; falls back to basic metadata if unavailable</li><li><strong>No video support</strong>: Video files in photo libraries are ignored</li><li><strong>No map view</strong>: GPS coordinates are stored but no map UI exists yet</li><li><strong>No thumbnail cache</strong>: Thumbnails are regenerated on each request</li><li><strong>No face detection</strong>: People/face tagging not supported</li></ol>`,33)])])}const g=e(d,[["render",s]]);export{u as __pageData,g as default};
